/**
 * Generated by `createschema ai.AISkill 'name:Text; description:Text; content:Text; license?:Text; compatibility?:Text; metadata?:Json; allowedTools?:Text; image?:File; examples?:Json; b2bApp:Relationship:B2BApp:SET_NULL; scope:Select:global,organization,personal; organization?:Relationship:Organization:SET_NULL; user?:Relationship:User:SET_NULL;' --force`
 */

const { throwAuthenticationError } = require('@open-condo/keystone/apolloErrorFormatter')

const { canDirectlyManageSchemaObjects } = require('@condo/domains/user/utils/directAccess')

/**
 * AISkills can be read by any authed non-deleted user:
 * 1. Admin / support → all skills
 * 2. Any authed user → all skills (skills are globally readable; availability gating happens on frontend)
 */
async function canReadAISkills ({ authentication: { item: user } }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false

    return {}
}

/**
 * AISkills can be managed by:
 * 1. Admin / support
 * 2. Users with direct access
 */
async function canManageAISkills ({ authentication: { item: user }, listKey, originalInput, operation }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isSupport || user.isAdmin) return true

    return await canDirectlyManageSchemaObjects(user, listKey, originalInput, operation)
}

/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canReadAISkills,
    canManageAISkills,
}
